<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Students Attendance</h1><p>Load, mark, reopen and update class attendance</p></div></header><section class="module-card"><header class="module-card__header"><div class="mode-switch"><button class="is-active" type="button">Manual Attendance</button><button class="locked-choice" disabled><i data-lucide="lock"></i>Card Scanning</button></div></header><div class="module-card__body"><form class="filter-bar" method="get"><div class="module-field"><label>Date</label><input class="module-input" name="date" type="date" value="<?= e($selectedDate) ?>" required></div><div class="module-field"><label>Class</label><select class="module-select" name="class" required><option value="">Select class</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary">Load Students</button></form><?php if($selectedClass):?><form method="post" action="<?= url('/admin/attendance/students') ?>"><?= csrf_field() ?><input type="hidden" name="date" value="<?= e($selectedDate) ?>"><input type="hidden" name="class" value="<?= $selectedClass ?>"><?php if(!$attendanceRows):?><div class="compact-empty"><h3>No active students found</h3></div><?php else:?><div class="table-tools"><button class="btn btn--secondary" type="button" onclick="document.querySelectorAll('.student-status').forEach(x=>x.value='Present')">Mark All Present</button></div><table class="data-table"><thead><tr><th>Registration</th><th>Student</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($attendanceRows as$row):?><tr><td><?= e($row['registration_no']) ?></td><td><?= e($row['student_name']) ?></td><td><select class="module-select student-status" name="status[<?= $row['id'] ?>]"><?php foreach(['Present','Absent','Leave']as$s):?><option <?= $row['attendance_status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></td><td><input class="module-input" name="remarks[<?= $row['id'] ?>]" value="<?= e($row['remarks']) ?>"></td></tr><?php endforeach ?></tbody></table><div class="module-card__footer"><button class="btn btn--primary">Save Attendance</button></div><?php endif ?></form><?php endif ?></div></section></div></div></main>
